import { firstValueFrom, ReplaySubject } from 'rxjs';

export class FfileService {
    private dirHandle$ = new ReplaySubject<FileSystemDirectoryHandle>(1);

    init(handle: FileSystemDirectoryHandle): void {
        this.dirHandle$.next(handle);
    }

    async getDir(): Promise<FileSystemDirectoryHandle> {
        return await firstValueFrom(this.dirHandle$);
    }

    async getFileBlob(filename: string): Promise<Blob> {
        const dir = await this.getDir();
        const fileHandle = await dir.getFileHandle(filename);
        return await fileHandle.getFile();
    }
}
