export const DB_VERSION = 26;

export class Video {
    id?: number;
    name!: string;
    raw!: string;
    durationMs!: number;
    endMs!: number;
    project!: string;
    prompt?: string;
    sort?: number;
    speed!: number;
    startMs!: number;
    audioLineText?: string;
    audioLineStartMs?: number;
    audioLineId?: number;
    selected!: boolean;
    width!: number;
    height!: number;
    timelineDisabled!: boolean;
    timelineDurationMs!: number;
    lane!: number;

    rgbaName(): string {
        return this.name + '.raw';
    }
}
