export class FopfsService {
    private fileHandles = new Map<string, FileSystemSyncAccessHandle>();

    async getSyncHandle(fileName: string): Promise<FileSystemSyncAccessHandle> {
        const cached = this.fileHandles.get(fileName);
        if (cached) return cached;
        const root = await navigator.storage.getDirectory();
        const fileHandle = await root.getFileHandle(fileName);
        const accessHandle = await fileHandle.createSyncAccessHandle();
        this.fileHandles.set(fileName, accessHandle);
        return accessHandle;
    }

    async createWritableStream(fileName: string): Promise<FileSystemWritableFileStream> {
        const root = await navigator.storage.getDirectory();
        const fileHandle = await root.getFileHandle(fileName, { create: true });
        return await fileHandle.createWritable();
    }

    async fileExists(fileName: string): Promise<boolean> {
        const root = await navigator.storage.getDirectory();
        try {
            const handle = await root.getFileHandle(fileName, { create: false });
            const file = await handle.getFile();
            return file.size > 0;
        } catch {
            return false;
        }
    }

    async deleteFile(fileName: string): Promise<void> {
        const root = await navigator.storage.getDirectory();
        try {
            const handle = this.fileHandles.get(fileName);
            if (handle) {
                handle.close();
                this.fileHandles.delete(fileName);
            }
            await root.removeEntry(fileName);
        } catch {
            // best-effort
        }
    }

    async clear(): Promise<void> {
        const root = await navigator.storage.getDirectory();
        const iter = root as unknown as AsyncIterable<[string, FileSystemHandle]>;
        for await (const [name, handle] of iter) {
            if (handle.kind === 'file') {
                await this.deleteFile(name);
            }
        }
        this.fileHandles.clear();
    }
}
