import { openDB, type IDBPDatabase, type OpenDBCallbacks } from 'idb';
import { firstValueFrom, ReplaySubject } from 'rxjs';

export class FidbService {
    private db$ = new ReplaySubject<IDBPDatabase>(1);

    initDb(version: number, upgradeCallback: OpenDBCallbacks<unknown>['upgrade']): void {
        openDB('😎', version, { upgrade: upgradeCallback })
            .then(v => this.db$.next(v))
            .catch(console.error);
    }

    async getById<T>(storeName: string, id: string | number): Promise<T | null> {
        const db = await firstValueFrom(this.db$);
        const tx = db.transaction(storeName, 'readonly');
        const store = tx.objectStore(storeName);
        const result = await store.get(id);
        return (result as T | undefined) ?? null;
    }
}
