/// <reference lib="webworker" />
import {
    animationFrames,
    BehaviorSubject,
    concatMap,
    distinctUntilChanged,
    exhaustMap,
    filter,
    fromEvent,
    map,
    ReplaySubject,
    share,
    takeUntil,
    tap,
    withLatestFrom,
} from 'rxjs';
import { FcanvasService } from './fcanvas.service';
import { FfileService } from './ffile.service';
import { FidbService } from './fidb.service';
import { FopfsService } from './fopfs.service';
import { DB_VERSION, Video } from './schema';

export interface InitPayload {
    canvas: OffscreenCanvas;
    clockBuffer: SharedArrayBuffer;
    loadVideoBuffer: SharedArrayBuffer;
    dirHandle: FileSystemDirectoryHandle;
    isDirChangeBuffer: SharedArrayBuffer;
    decoderPorts: MessagePort[];
}

const fopfs = new FopfsService();
const ffile = new FfileService();
const fidb = new FidbService();
const openHandles = new Map<string, FileSystemSyncAccessHandle>();
const textDecoder = new TextDecoder();

const fcanvas$ = new ReplaySubject<FcanvasService>(1);
const rawCanvas$ = new ReplaySubject<OffscreenCanvas>(1);
const clockView$ = new ReplaySubject<Float64Array>(1);
const loadDataView$ = new ReplaySubject<Uint8Array>(1);
const isDirChangeView$ = new ReplaySubject<Uint8Array>(1);
const activeSequence$ = new BehaviorSubject<Video[]>([]);
const workerMessages$ = fromEvent<MessageEvent>(self, 'message');
const init$ = workerMessages$.pipe(
    filter(e => e.data.type === 'INIT'),
    map(e => e.data.payload as InitPayload),
);
const cleanup$ = workerMessages$.pipe(filter(e => e.data.type === 'CLEANUP'));
const decodePorts$ = new ReplaySubject<MessagePort[]>(1);

init$.subscribe(payload => {
    fidb.initDb(DB_VERSION, () => {});
    ffile.init(payload.dirHandle);
    fcanvas$.next(new FcanvasService(payload.canvas));
    rawCanvas$.next(payload.canvas);
    clockView$.next(new Float64Array(payload.clockBuffer));
    loadDataView$.next(new Uint8Array(payload.loadVideoBuffer));
    isDirChangeView$.next(new Uint8Array(payload.isDirChangeBuffer));
    decodePorts$.next(payload.decoderPorts);
    console.log('[canvas.worker] Booted and dependencies loaded.');
});

const tick$ = animationFrames().pipe(takeUntil(cleanup$), share());
let tickLogCounter = 0;

const loadVideos$ = tick$.pipe(
    tap(() => {
        if (tickLogCounter++ % 600 === 0) {
            console.log('[canvas.worker] ⏱️ tick$ is alive and looping...');
        }
    }),
    withLatestFrom(loadDataView$, isDirChangeView$),
    filter(([, loadDataView]) => loadDataView.some(f => f !== 32)),
    map(([, loadDataView, isDirChangeView]) => {
        const unsharedView = new Uint8Array(loadDataView);
        const jsonString = textDecoder.decode(unsharedView).trim();
        try {
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const rawParsed = JSON.parse(jsonString) as any[];
            const a = rawParsed.map(v => Object.assign(new Video(), v));
            console.log('[canvas.worker] Loaded video buffer...', a);
            return { parsedVideos: a, isDirChangeView };
        } catch (e) {
            console.error('[canvas.worker] JSON parse error:', e);
            return { parsedVideos: [] as Video[], isDirChangeView };
        } finally {
            loadDataView$.next(loadDataView.fill(32));
        }
    }),
    concatMap(async ({ parsedVideos, isDirChangeView }) => {
        if (isDirChangeView[0] === 1) {
            console.log('[canvas.worker] 🗄️ Directory change detected via SAB switch!');
            isDirChangeView[0] = 0;
            const dirItem = await fidb.getById<{ handle: FileSystemDirectoryHandle }>(
                'handles',
                'dir',
            );
            if (dirItem && dirItem.handle) {
                ffile.init(dirItem.handle);
                activeSequence$.next([]);
                openHandles.forEach(h => h.close());
                openHandles.clear();
                await fopfs.clear();
                console.log('[canvas.worker] ✨ OPFS Cleared.');
            }
        }
        return parsedVideos;
    }),
    withLatestFrom(decodePorts$),
    exhaustMap(async ([parsedVideos, decodePorts]) => {
        const copyPromises = parsedVideos.map(async (video, i) => {
            if (openHandles.has(video.rgbaName())) return;
            const exists = await fopfs.fileExists(video.rgbaName());
            if (!exists) {
                const dir = await ffile.getDir();
                if (await dir.getFileHandle(video.rgbaName()).catch(() => null)) {
                    const rawBlob = await ffile.getFileBlob(video.rgbaName());
                    const stream = await fopfs.createWritableStream(video.rgbaName());
                    await rawBlob.stream().pipeTo(stream);
                    console.log(`[OPFS] ✅ FINISHED copying ${video.rgbaName()}`);
                } else {
                    await new Promise<void>((resolve, reject) => {
                        const port = decodePorts[i % decodePorts.length]!;
                        const handler = (e: MessageEvent) => {
                            if (e.data.id === video.name) {
                                port.removeEventListener('message', handler);
                                if (e.data.status === 'DONE') resolve();
                                else reject(new Error(e.data.error));
                            }
                        };
                        port.addEventListener('message', handler);
                        port.start();
                        port.postMessage({
                            id: video.name,
                            type: 'DECODE',
                            payload: { mp4Name: video.name, rawName: video.rgbaName() },
                        });
                    });
                }
            }
            if (!openHandles.has(video.rgbaName())) {
                openHandles.set(video.rgbaName(), await fopfs.getSyncHandle(video.rgbaName()));
            }
        });
        await Promise.all(copyPromises);
        activeSequence$.next(parsedVideos);
        console.log(`[canvas.worker] Sequence updated: ${parsedVideos.length} total videos`);
    }),
);

const activeVideo$ = tick$.pipe(
    withLatestFrom(clockView$, activeSequence$),
    map(([, clockView, activeSequence]) => {
        const globalMs = clockView[0]!;
        const playingVideos = activeSequence.filter(v => {
            if (
                v.timelineDisabled ||
                v.audioLineStartMs === undefined ||
                v.startMs === undefined ||
                v.endMs === undefined
            ) {
                return false;
            }
            const speedFactor = (v.speed > 0 ? v.speed : 100) / 100;
            const timelineEndMs = v.audioLineStartMs + (v.endMs - v.startMs) / speedFactor;
            return globalMs >= v.audioLineStartMs && globalMs < timelineEndMs;
        });
        // 👉 Just one clean line. If empty, it naturally returns undefined!
        return playingVideos.sort((a, b) => (a.lane ?? 0) - (b.lane ?? 0))[0];
    }),
    filter((video): video is Video => {
        if (!video) return false;
        const handle = openHandles.get(video.rgbaName());
        return !!handle;
    }),
);

const render$ = activeVideo$.pipe(
    withLatestFrom(fcanvas$, rawCanvas$, clockView$),
    map(([activeVideo, fcanvas, rawCanvas, clockView]) => {
        const globalMs = clockView[0]!;
        const expectedBytes = activeVideo.width * activeVideo.height * 4;

        const speedFactor = (activeVideo.speed > 0 ? activeVideo.speed : 100) / 100;
        const elapsedOnTimelineMs = globalMs - activeVideo.audioLineStartMs!;
        const localSourceMs = activeVideo.startMs! + elapsedOnTimelineMs * speedFactor;

        const handle = openHandles.get(activeVideo.rgbaName())!;

        const totalBytes = handle.getSize();
        const totalFrames = Math.floor(totalBytes / expectedBytes);
        const msPerFrame = activeVideo.durationMs / totalFrames;

        let targetFrameIndex = Math.floor(localSourceMs / msPerFrame);
        if (targetFrameIndex < 0) targetFrameIndex = 0;
        if (targetFrameIndex >= totalFrames) targetFrameIndex = totalFrames - 1;

        const byteOffset = targetFrameIndex * expectedBytes;

        return {
            activeVideo,
            fcanvas,
            rawCanvas,
            expectedBytes,
            targetFrameIndex,
            byteOffset,
            handle,
        };
    }),
    distinctUntilChanged(
        (prev, curr) =>
            prev.activeVideo.rgbaName() === curr.activeVideo.rgbaName() &&
            prev.targetFrameIndex === curr.targetFrameIndex,
    ),
    exhaustMap(async ({ activeVideo, fcanvas, rawCanvas, expectedBytes, byteOffset, handle }) => {
        if (rawCanvas.width !== activeVideo.width || rawCanvas.height !== activeVideo.height) {
            rawCanvas.width = activeVideo.width;
            rawCanvas.height = activeVideo.height;
        }
        const buffer = new Uint8Array(expectedBytes);
        if (handle.read(buffer, { at: byteOffset }) === expectedBytes) {
            fcanvas.draw(buffer);
        }
    }),
);

cleanup$.subscribe(() => {
    openHandles.forEach(h => h.close());
    openHandles.clear();
    console.log('[canvas.worker] Terminated.');
});

loadVideos$.subscribe();
render$.subscribe({
    error: err => console.error('[canvas.worker] Render stream crashed:', err),
});
