export class FcanvasService {
    private ctx: OffscreenCanvasRenderingContext2D;
    private canvas: OffscreenCanvas;
    private imageData: ImageData | null = null;
    private currentWidth = 0;
    private currentHeight = 0;

    constructor(canvas: OffscreenCanvas) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d', { alpha: false }) as OffscreenCanvasRenderingContext2D;
    }

    draw(buffer: Uint8Array): void {
        if (
            !this.imageData ||
            this.currentWidth !== this.canvas.width ||
            this.currentHeight !== this.canvas.height
        ) {
            this.currentWidth = this.canvas.width;
            this.currentHeight = this.canvas.height;
            const clamped = new Uint8ClampedArray(buffer.buffer as ArrayBuffer);
            this.imageData = new ImageData(clamped, this.currentWidth, this.currentHeight);
        } else {
            this.imageData.data.set(buffer);
        }
        this.ctx.putImageData(this.imageData, 0, 0);
    }
}
